INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('company-fundamentals', 'Company Fundamentals', 'Screener filters by revenue, margin, EPS, and debt — this course teaches what those numbers actually mean before you touch the filters.', 'BarChart3', 'blue', 4, 'beginner', FALSE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'company-fundamentals'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('revenue-profit-margins', 'Revenue, Profit & Margins', 'read', 0, 10, '{"sections":[{"text":"Imagine a lemonade stand that sells $100 worth of lemonade in a day. That $100 is the Revenue — all the money coming in from sales before you subtract any costs. It''s the top number on a company''s report, which is why people call it the ''top line.''","highlightedTerms":[{"term":"Revenue","definition":"All money the company earned from selling products or services — before any costs are subtracted."}]},{"text":"But making lemonade isn''t free — you buy lemons, sugar, cups, and maybe pay a helper. After you subtract all those costs (and taxes too), what''s left is your Net Income, also called profit. If your $100 in sales cost you $80 to run, your net income is just $20.","highlightedTerms":[{"term":"Net Income","definition":"The final profit after every cost — taxes, interest, and all other expenses — has been subtracted. The \"bottom line.\""}]},{"text":"Profit Margin turns that profit into a percentage: net income divided by revenue. In our example, $20 profit on $100 in sales is a 20% margin. It answers a simple question: out of every dollar that comes in, how many cents do you actually keep?","highlightedTerms":[{"term":"Profit Margin","definition":"What percentage of revenue the company keeps as profit after all costs. A 20% margin means the company keeps $0.20 for every $1.00 it earns."}]},{"text":"Here''s why margin matters more than raw dollars when comparing companies of different sizes. A giant store might earn $1 billion in profit but only keep 2 cents per dollar (a 2% margin), while a small software firm keeps 30 cents per dollar (a 30% margin). The smaller company is actually far more efficient at turning sales into profit — and margin reveals that instantly.","highlightedTerms":[{"term":"Profit Margin","definition":"What percentage of revenue the company keeps as profit after all costs. A 20% margin means the company keeps $0.20 for every $1.00 it earns."}]}],"funFact":"Grocery stores are famous for razor-thin margins — often around 1-3%. They make money by selling huge volumes, not by keeping much profit on each item."}'::jsonb),
  ('eps-and-pe-ratio', 'EPS & the P/E Ratio', 'read', 1, 10, '{"sections":[{"text":"Imagine a company splits all of its yearly profit into equal slices — one slice for each share of stock. That slice is called EPS (Diluted), or earnings per share. You calculate it by taking the company''s Net Income (its total profit) and dividing it by the number of shares that exist. So if a company earns $100 million and has 50 million shares, each share ''earned'' $2.","highlightedTerms":[{"term":"EPS (Diluted)","definition":"Net income divided by the number of shares. Shows how much profit each share of stock represents."},{"term":"Net Income","definition":"The final profit after every cost — taxes, interest, and all other expenses — has been subtracted. The \"bottom line.\""}]},{"text":"Now, how do you know if a stock''s price is expensive or cheap compared to what it earns? That''s where the P/E (TTM) ratio comes in — it divides the share price by the EPS. If a stock costs $40 and earned $2 per share, its P/E is 20. In plain terms: you''re paying $20 for every $1 of yearly profit.","highlightedTerms":[{"term":"P/E (TTM)","definition":"How much investors pay per $1 of profit the company earned in the past 12 months. Lower often signals better value — but context matters."}]},{"text":"A high P/E often means investors expect strong future growth — they''re happy to pay more today betting profits will rise. A low P/E can mean a stock is a bargain, or that investors worry its earnings might shrink. Neither number is ''good'' or ''bad'' on its own.","highlightedTerms":[{"term":"Rev Growth","definition":"How fast the company''s total sales are growing year-over-year. Positive means the business is expanding."}]},{"text":"Here''s the key caveat: there is no single ''good'' P/E in a vacuum. A fast-growing tech company might trade at a P/E of 40 while a steady utility sits at 12 — and both can be perfectly reasonable. Always compare a P/E to the company''s own growth and to other companies in the same industry.","highlightedTerms":[{"term":"Forward P/E","definition":"Like P/E but uses analyst estimates for future earnings. Useful for fast-growing companies where future profits matter more than past ones."}]}],"funFact":"During the dot-com bubble around 2000, some companies had no profits at all — meaning their P/E ratio couldn''t even be calculated, since you can''t divide by zero earnings!"}'::jsonb),
  ('fundamentals-quiz', 'Quick Check: Fundamentals', 'quiz', 2, 20, '{"questions":[{"question":"A lemonade stand takes in $100 from selling lemonade, but spends $70 on lemons, sugar, and cups. What is its net income (the money left after all costs)?","options":["$100","$70","$30","$170"],"correctIndex":2,"explanation":"Revenue is the total money coming in ($100), but net income is what''s left after paying all the costs ($100 - $70 = $30). Net income is the real ''take-home'' profit."},{"question":"A company earns $1,000,000 in net income and has 500,000 shares of stock. What is its EPS (earnings per share)?","options":["$0.50","$2.00","$5.00","$500,000"],"correctIndex":1,"explanation":"EPS is net income divided by the number of shares: $1,000,000 ÷ 500,000 = $2.00. It tells you how much profit belongs to each single share."},{"question":"A stock trades at $50 per share and has an EPS of $5. What is its P/E ratio, and what does it roughly mean?","options":["10 — you pay $10 for every $1 of yearly profit per share","0.10 — you pay 10 cents for every $1 of yearly profit per share","250 — the company is very expensive","5 — the stock costs 5 times its earnings"],"correctIndex":0,"explanation":"P/E is price divided by EPS: $50 ÷ $5 = 10. It means you''re paying $10 for each $1 of the company''s yearly profit per share — a quick way to gauge how pricey a stock is."}]}'::jsonb),
  ('fundamentals-match', 'Match the Fundamentals', 'match', 3, 15, '{"pairs":[{"term":"Revenue","definition":"All the money a company brings in from sales, before any costs."},{"term":"Net Income","definition":"What''s left over after a company pays all its bills and taxes."},{"term":"Profit Margin","definition":"How much of each sales dollar a company keeps as profit."},{"term":"EPS","definition":"A company''s profit split across each share of stock you can own."},{"term":"P/E Ratio","definition":"The stock''s price compared to how much it earns per share."}]}'::jsonb),
  ('cash-flow-and-debt', 'Cash Flow & Debt', 'read', 4, 10, '{"sections":[{"text":"Imagine a lemonade stand that reports a big profit on paper but has an empty cash box. How? Because ''profit'' and ''cash'' aren''t the same thing. Net Income is the profit a company reports after all expenses, but it includes items where no actual cash moved. Operating Cash Flow shows the real money that flowed in and out from running the business.","highlightedTerms":[{"term":"Net Income","definition":"The final profit after every cost — taxes, interest, and all other expenses — has been subtracted. The \"bottom line.\""},{"term":"Operating Cash Flow","definition":"Actual cash generated by the company''s core operations. Often considered more reliable than net income because it''s harder to manipulate."}]},{"text":"One big reason the two numbers differ is non-cash expenses. For example, D&A (depreciation and amortization) spreads the cost of things like machines or patents over many years, lowering reported profit even though no cash left the company that year. Timing also matters: a company might record a sale today but not collect the cash for months, so profit looks high while the bank account stays flat.","highlightedTerms":[{"term":"D&A","definition":"A non-cash accounting expense that spreads the cost of assets over their useful life. Added back to calculate operating cash flow."}]},{"text":"Debt tells a different part of the story. The debt-to-equity ratio compares how much a company has borrowed (Long-Term Debt and other liabilities) to what its owners have invested (Stockholders'' Equity). A high ratio means the company leans heavily on borrowed money, which can boost growth but also raises risk if profits dip and loans still need repaying.","highlightedTerms":[{"term":"Long-Term Debt","definition":"Debt that doesn''t come due for more than a year. High long-term debt can be risky if interest rates rise or the business slows."},{"term":"Stockholders'' Equity","definition":"What shareholders would receive if all assets were sold and all debts paid. Total Assets minus Total Liabilities."}]},{"text":"So when you study a company, don''t just cheer for a big profit number. Check whether real cash is coming in through Free Cash Flow, and see how much debt sits on the balance sheet. Strong cash flow plus manageable debt is usually a sign of a healthier, more resilient business.","highlightedTerms":[{"term":"Free Cash Flow","definition":"Operating cash flow minus capital expenditures. Money the company can use to pay dividends, buy back shares, or pay down debt."}]}],"funFact":"Some fast-growing companies report years of losses on paper while quietly generating positive cash flow — Amazon famously showed thin or negative profits for years while its cash machine hummed along."}'::jsonb),
  ('cheap-or-expensive', 'Cheap or Expensive?', 'scenario', 5, 25, '{"setup":"I''m comparing two companies. Company A trades at a P/E of 12 (meaning its price is 12 times its yearly earnings per share) — that sounds ''cheap.'' Company B has a P/E of 28, which sounds ''expensive.'' But when I dig deeper: Company A''s profit margins have been shrinking for three straight years and it''s carrying a lot of debt. Company B''s margins are steadily growing and it has almost no debt. Which one is actually the better value?","choices":[{"label":"Company A — a P/E of 12 is lower, so it''s obviously the cheaper, better deal.","feedback":"Totally understandable — a low P/E does look like a bargain at first glance. But P/E is just one snapshot. Company A''s shrinking margins mean it''s keeping less profit from each sale over time, and heavy debt makes it fragile if business slows. A ''cheap'' price can be a warning sign, not a gift. The market may be pricing it low for good reasons.","isCorrect":false},{"label":"Company B — its growing margins and low debt suggest a healthier business, which can justify the higher P/E.","feedback":"Nicely reasoned! You looked past the single number. Company B''s rising margins mean it''s getting more profitable over time, and low debt means it''s on solid financial footing. Investors often willingly pay a higher P/E for a strong, growing, low-risk business — and that can make it the better long-term value even though it looks ''expensive.''","isCorrect":true},{"label":"I can''t decide from this — I''d flip a coin since both have a P/E number.","feedback":"It''s honest to feel unsure, and slowing down is smart! But you actually have plenty of clues here. Instead of guessing, compare the trends: one company is getting weaker (falling margins, high debt) while the other is getting stronger (rising margins, low debt). The full picture points clearly toward the healthier business.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
